    }

    @media (min-width: 640px) {
      .blank-slate--default {
        display: none;
      }
    }
  }
}

.cards__new-column {
  position: relative;

  @media (max-width: 639px) {
    inset-inline-end: 0;
    position: absolute;
    translate: 100%;
